import subprocess, sys

def q(s):
    """YAML double-quoted source that safe_load parses to exactly s."""
    out=['"']
    for ch in s:
        c=ord(ch)
        if ch=='"': out.append('\\"')
        elif ch=='\\': out.append('\\\\')
        elif 0x20<=c<=0x7e: out.append(ch)
        elif c<=0xff: out.append('\\x%02X'%c)
        elif c<=0xffff: out.append('\\u%04X'%c)
        else: out.append('\\U%08X'%c)
    out.append('"')
    return ''.join(out)

def run(arg):
    r = subprocess.run(['/workspace/dataset/test15_executable','--a',arg],capture_output=True)
    return r.returncode, r.stdout.decode('utf-8','replace'), r.stderr.decode('utf-8','replace')

def show(arg, label=None):
    rc,out,err = run(arg)
    print('### %s' % (label if label else repr(arg)))
    if rc!=0:
        el = err.strip().splitlines()
        print('   RC=%d ERR=%s' % (rc, el[-1] if el else ''))
        return None
    lines = out.split('\n')
    # drop the two trailing '' entries (dump \n + print \n) -> actually out ends '\n\n'
    for i,l in enumerate(lines):
        print('   %2d|%s|%d' % (i,l,len(l)))
    return out

def sc(s, label=None):
    """probe a root-level scalar equal to python string s"""
    return show(q(s), label if label else 'ROOT '+repr(s))
